<?php
declare(strict_types=1);
final class DocumentAnalysisService {
 private PDO $db;private GoogleDriveClient $drive;private OpenAIClient $openai;private int $maxBytes;
 public function __construct(PDO $db,GoogleDriveClient $drive,OpenAIClient $openai,int $maxBytes){$this->db=$db;$this->drive=$drive;$this->openai=$openai;$this->maxBytes=$maxBytes;}
 public function register(string $driveUrl,?int $companyId,?int $grantId,int $userId):array {$fileId=GoogleDriveClient::fileIdFromUrl($driveUrl);$meta=$this->drive->metadata($fileId);$modified=isset($meta['modifiedTime'])?date('Y-m-d H:i:s',strtotime($meta['modifiedTime'])):null;$hash=$meta['md5Checksum']??hash('sha256',$fileId.'|'.($meta['modifiedTime']??''));$sql='INSERT INTO documents(company_id,grant_program_id,drive_file_id,drive_url,original_name,mime_type,file_size,source_modified_at,content_hash,created_by)VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE drive_url=VALUES(drive_url),original_name=VALUES(original_name),mime_type=VALUES(mime_type),file_size=VALUES(file_size),analysis_status=IF(content_hash<>VALUES(content_hash),\'stale\',analysis_status),source_modified_at=VALUES(source_modified_at),content_hash=VALUES(content_hash),updated_at=CURRENT_TIMESTAMP';$st=$this->db->prepare($sql);$st->execute([$companyId,$grantId,$fileId,$driveUrl,$meta['name'],$meta['mimeType'],isset($meta['size'])?(int)$meta['size']:null,$modified,$hash,$userId]);$id=(int)$this->db->lastInsertId();if(!$id){$q=$this->db->prepare('SELECT id FROM documents WHERE drive_file_id=?');$q->execute([$fileId]);$id=(int)$q->fetchColumn();}return ['id'=>$id,'name'=>$meta['name'],'status'=>'registered'];}
 public function analyze(int $documentId):array {$st=$this->db->prepare('SELECT * FROM documents WHERE id=?');$st->execute([$documentId]);$doc=$st->fetch();if(!$doc)throw new RuntimeException('문서를 찾을 수 없습니다.');$this->db->prepare("UPDATE documents SET analysis_status='processing',error_message=NULL WHERE id=?")->execute([$documentId]);$temp=null;$openaiFile=null;try{$meta=$this->drive->metadata($doc['drive_file_id']);$temp=$this->drive->downloadToTemp($meta,$this->maxBytes);$openaiFile=$this->openai->upload($temp,$doc['original_name']);$type=$doc['grant_program_id']?'공모사업 공고문':'기업 진단자료';$result=$this->openai->analyze($openaiFile,$type);$analysis=json_encode($result['data'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$evidence=json_encode($result['data']['evidence']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$up=$this->db->prepare("UPDATE documents SET analysis_status='completed',analysis_json=?,evidence_json=?,analysis_version=analysis_version+1,analyzed_at=NOW(),error_message=NULL WHERE id=?");$up->execute([$analysis,$evidence,$documentId]);return ['id'=>$documentId,'status'=>'completed','analysis'=>$result['data']];}catch(Throwable $e){$this->db->prepare("UPDATE documents SET analysis_status='failed',error_message=? WHERE id=?")->execute([substr($e->getMessage(),0,1000),$documentId]);throw $e;}finally{if($openaiFile)$this->openai->deleteFile($openaiFile);if($temp&&is_file($temp)){file_put_contents($temp,'');unlink($temp);}}}
}
